describe('Prefers Reduced Motion Accessibility', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should respect prefers-reduced-motion: reduce setting', () => {
    // Set the prefers-reduced-motion media query to 'reduce'
    cy.window().then((win) => {
      const mediaQueryList = win.matchMedia('(prefers-reduced-motion: reduce)');
      Object.defineProperty(mediaQueryList, 'matches', {
        writable: true,
        value: true,
      });
    });

    // Reload to apply the media query
    cy.reload();

    // Verify that animations are disabled
    cy.get('[data-testid="animated-element"]').should('exist');
    cy.get('[data-testid="animated-element"]').then(($element) => {
      const computedStyle = window.getComputedStyle($element[0]);
      const animationDuration = computedStyle.animationDuration;
      const transitionDuration = computedStyle.transitionDuration;

      // Animation and transition durations should be 0s or none
      expect(animationDuration).to.match(/^0s|none$/);
      expect(transitionDuration).to.match(/^0s|none$/);
    });

    // Verify CSS classes or attributes that disable animations are applied
    cy.get('body').should('have.class', 'reduce-motion');
  });

  it('should not apply reduced motion when prefers-reduced-motion: no-preference is set', () => {
    // Set the prefers-reduced-motion media query to 'no-preference'
    cy.window().then((win) => {
      const mediaQueryList = win.matchMedia('(prefers-reduced-motion: no-preference)');
      Object.defineProperty(mediaQueryList, 'matches', {
        writable: true,
        value: true,
      });
    });

    cy.reload();

    // Verify that animations are enabled
    cy.get('[data-testid="animated-element"]').should('exist');
    cy.get('[data-testid="animated-element"]').then(($element) => {
      const computedStyle = window.getComputedStyle($element[0]);
      const animationDuration = computedStyle.animationDuration;
      const transitionDuration = computedStyle.transitionDuration;

      // Animation and transition durations should not be 0s
      expect(animationDuration).not.to.match(/^0s$/);
      expect(transitionDuration).not.to.match(/^0s$/);
    });

    // Verify reduce-motion class is not applied
    cy.get('body').should('not.have.class', 'reduce-motion');
  });

  it('should handle dynamic changes to prefers-reduced-motion setting', () => {
    // Start with no preference
    cy.window().then((win) => {
      const mediaQueryList = win.matchMedia('(prefers-reduced-motion: no-preference)');
      Object.defineProperty(mediaQueryList, 'matches', {
        writable: true,
        value: true,
      });
    });

    cy.reload();
    cy.get('body').should('not.have.class', 'reduce-motion');

    // Simulate user changing system preference to reduce motion
    cy.window().then((win) => {
      const mediaQueryList = win.matchMedia('(prefers-reduced-motion: reduce)');
      Object.defineProperty(mediaQueryList, 'matches', {
        writable: true,
        value: true,
      });

      // Trigger the change event
      const event = new Event('change');
      mediaQueryList.dispatchEvent(event);
    });

    // Verify the app responds to the change
    cy.get('body').should('have.class', 'reduce-motion');
  });

  it('should apply reduced motion to all animated components', () => {
    cy.window().then((win) => {
      const mediaQueryList = win.matchMedia('(prefers-reduced-motion: reduce)');
      Object.defineProperty(mediaQueryList, 'matches', {
        writable: true,
        value: true,
      });
    });

    cy.reload();

    // Check multiple animated elements
    cy.get('[data-testid^="animated-"]').each(($element) => {
      cy.wrap($element).then(($el) => {
        const computedStyle = window.getComputedStyle($el[0]);
        const animationDuration = computedStyle.animationDuration;
        const transitionDuration = computedStyle.transitionDuration;

        expect(animationDuration).to.match(/^0s|none$/);
        expect(transitionDuration).to.match(/^0s|none$/);
      });
    });
  });

  it('should maintain functionality while respecting reduced motion', () => {
    cy.window().then((win) => {
      const mediaQueryList = win.matchMedia('(prefers-reduced-motion: reduce)');
      Object.defineProperty(mediaQueryList, 'matches', {
        writable: true,
        value: true,
      });
    });

    cy.reload();

    // Verify interactive elements still work
    cy.get('[data-testid="interactive-button"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    // Verify content is accessible without animations
    cy.get('[data-testid="modal"]').should('contain', 'Expected content');
  });
});
